<template>
  <div class="disputes-page">
    <AdminListToolbar><el-input v-model="filters.keyword" clearable placeholder="订单号／异议说明" style="width:260px" @keyup.enter="search" /><el-checkbox v-model="filters.overdue" @change="search">仅看处理超期</el-checkbox><el-button type="primary" @click="search">搜索</el-button><el-button @click="reset">重置</el-button></AdminListToolbar>
    <el-tabs v-model="filters.status" class="tabs" @tab-change="search"><el-tab-pane v-for="tab in tabs" :key="tab.value" :label="tab.label" :name="tab.value" /></el-tabs>
    <AdminListTable :data="rows" :loading="loading" :error="error" @retry="load">
      <el-table-column label="异议／订单" min-width="220"><template #default="{ row }"><el-button type="primary" link @click="open(row)">异议 #{{ row.id }}</el-button><div class="muted">{{ row.orderNo }}</div></template></el-table-column>
      <el-table-column label="患者" min-width="130"><template #default="{ row }"><strong>{{ row.user?.nickname || '微信用户' }}</strong><div class="muted">{{ row.user?.phoneMasked }}</div></template></el-table-column>
      <el-table-column label="服务记录" min-width="180"><template #default="{ row }"><strong>{{ row.itemName }}</strong><div class="muted">{{ row.institutionName }}</div></template></el-table-column>
      <el-table-column label="进度" min-width="140"><template #default="{ row }"><el-tag :type="row.status === 'resolved' ? 'success' : 'warning'">{{ statusText(row.status) }}</el-tag><div class="muted">{{ row.ownerName || '等待客服受理' }}</div></template></el-table-column>
      <el-table-column label="反馈期限" min-width="180"><template #default="{ row }"><span :class="{ overdue: isOverdue(row) }">{{ row.deadline ? formatTime(row.deadline) : row.status === 'resolved' ? '已结案' : '等待患者／退款结果' }}</span></template></el-table-column>
      <el-table-column label="操作" width="58" fixed="right" align="center"><template #default="{ row }"><AdminListAction label="查看处理" icon="View" @click="open(row)" /></template></el-table-column>
    </AdminListTable>
    <div class="pagination"><span>共 {{ total }} 条</span><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev, pager, next" @current-change="load" /></div>
    <el-drawer v-model="visible" title="服务异议处理" size="700px">
      <template v-if="selected">
        <section class="summary"><el-tag>{{ statusText(selected.status) }}</el-tag><h3>{{ selected.itemName }}</h3><p>{{ selected.orderNo }} · {{ selected.institutionName }}</p><p>客服负责人：{{ selected.ownerName || '尚未受理' }}</p><p v-if="selected.deadline" :class="{ overdue: isOverdue(selected) }">下一次反馈期限：{{ formatTime(selected.deadline) }}</p></section>
        <el-alert v-if="selected.settlementHeld" title="异议尚未解决，相关记录保留结算暂停标记；其他无争议内容可继续处理。" :closable="false" type="warning" />
        <section class="panel"><h4>患者异议与原服务记录</h4><p>{{ selected.description }}</p><p>实际执行人员：{{ selected.performedByName || '未登记' }} · 完成时间：{{ selected.completedAt ? formatTime(selected.completedAt) : '—' }}</p><p v-if="selected.evidence">机构依据：{{ selected.evidence }}</p></section>
        <section v-if="selected.proposal" class="panel"><h4>当前处理方案 · {{ outcomeText(selected.outcome) }}</h4><p>{{ selected.proposal }}</p><p v-if="selected.restoredExpiresAt">恢复后有效期至 {{ formatTime(selected.restoredExpiresAt) }}</p><p v-if="selected.outcome === 'refund'">例外退费 ¥{{ (selected.refundAmountFen / 100).toFixed(2) }} · 承担方 {{ selected.costBearer }}<br>冲回口径：{{ selected.clawbackNote }}</p><p v-if="selected.refundId">关联退款 #{{ selected.refundId }} · {{ selected.refundStatus }}；在服务退款入口由独立管理账号审核</p></section>
        <section class="panel"><h4>处理历史</h4><el-timeline><el-timeline-item v-for="entry in [...selected.events].reverse()" :key="entry.id" :timestamp="formatTime(entry.createdAt)"><strong>{{ eventText(entry.eventType) }}</strong><p>{{ entry.detail }}</p></el-timeline-item></el-timeline></section>
      </template>
      <template #footer><div class="footer"><el-button @click="refresh">刷新</el-button><el-button v-if="selected?.deadline && !isOverdue(selected)" @click="act('extend')">说明延期</el-button><el-button v-if="selected?.status === 'submitted'" type="primary" @click="act('contact')">受理并联系</el-button><el-button v-if="selected?.status === 'evidence_pending'" type="primary" @click="act('evidence')">登记机构依据</el-button><el-button v-if="selected && (['processing','disputed','proposed'].includes(selected.status) || (selected.status === 'executing' && ['rejected','withdrawn'].includes(selected.refundStatus || '')))" type="primary" @click="act('propose')">提出处理方案</el-button><el-button v-if="selected && ['review_requested','disputed','review_proposed'].includes(selected.status)" type="primary" @click="act('review')">独立复核</el-button><el-button v-if="selected?.status === 'awaiting_rebooking'" type="primary" @click="act('finish_rearrange')">关联重新预约结果</el-button><el-button v-if="selected?.status === 'executing' && ['rejected','withdrawn'].includes(selected.refundStatus || '')" type="primary" @click="act('retry_refund')">重新生成退费申请</el-button></div></template>
    </el-drawer>
    <el-dialog v-model="actionVisible" :title="actionTitle" width="580px" append-to-body>
      <el-alert title="处理依据对患者可见。原登记人不能自行终结异议；复核人需与原方案提出人不同。" :closable="false" />
      <el-form label-position="top" class="action-form">
        <el-form-item v-if="form.action === 'contact'" label="客服负责人"><el-input v-model="form.ownerName" maxlength="60" placeholder="实际联系患者的客服姓名" /></el-form-item>
        <template v-if="['propose', 'review'].includes(form.action)">
          <el-form-item label="处理结果"><el-select v-model="form.outcome" style="width:100%"><el-option label="维持原记录" value="maintain" /><el-option label="纠正实际项目，调整双方次数" value="correct_item" /><el-option label="纠正扣次，恢复 1 次权益" value="restore" /><el-option label="重新安排，恢复 1 次后由患者预约" value="rearrange" /><el-option label="例外退费，保留真实履约记录" value="refund" /></el-select></el-form-item>
          <el-form-item v-if="form.outcome === 'correct_item'" label="实际完成的套餐服务项目"><el-select v-model="form.correctedEntitlementId" placeholder="选择其他有未使用次数的项目"><el-option v-for="item in correctedOptions" :key="item.id" :value="item.id" :label="item.name" /></el-select></el-form-item>
          <el-form-item v-if="['restore','rearrange','correct_item'].includes(form.outcome)" label="恢复后的有效期（已到期时必填）"><el-date-picker v-model="form.restoredExpiresAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss.SSSZ" /></el-form-item>
          <template v-if="form.outcome === 'refund'"><el-form-item :label="`例外退费金额（元），当前上限 ¥${((selected?.refundLimitFen || 0) / 100).toFixed(2)}`"><el-input-number v-model="form.amountYuan" :min="0" :max="(selected?.refundLimitFen || 0) / 100" :precision="2" /></el-form-item><el-form-item label="补偿承担方"><el-select v-model="form.costBearer"><el-option label="平台" value="platform" /><el-option label="机构" value="institution" /><el-option label="共同承担，具体见说明" value="shared" /></el-select></el-form-item><el-form-item label="机构／主理人冲回口径（仅管理端）"><el-input v-model="form.clawbackNote" type="textarea" maxlength="1000" placeholder="明确是否冲回及由谁承担；本次仅记录口径，结算账本另行开发" /></el-form-item></template>
        </template>
        <el-form-item v-if="form.action === 'finish_rearrange'" label="患者接受方案后建立的已确认预约"><el-select v-model="form.replacementAppointmentId" placeholder="选择新预约" style="width:100%"><el-option v-for="item in replacementOptions" :key="item.id" :value="item.id" :label="`预约 #${item.id} · ${formatTime(item.confirmedStartAt || item.requestedStartAt)}`" /></el-select></el-form-item>
        <el-form-item v-if="form.action === 'extend'" label="下一次反馈时间"><el-date-picker v-model="form.deadline" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss.SSSZ" /></el-form-item>
        <el-form-item label="联系情况／业务依据／处理说明"><el-input v-model="form.note" type="textarea" :rows="4" maxlength="2000" placeholder="说明业务事实、依据和下一步安排，不填写专业诊疗资料" /></el-form-item>
      </el-form>
      <template #footer><el-button @click="actionVisible = false">取消</el-button><el-button type="primary" :loading="submitting" @click="save">保存并通知患者</el-button></template>
    </el-dialog>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage } from 'element-plus'
import AdminListAction from '@/components/AdminListAction.vue'
import AdminListTable from '@/components/AdminListTable.vue'
import AdminListToolbar from '@/components/AdminListToolbar.vue'
import { serviceProgramApi, type ServiceDispute, type ServiceAppointment } from '@/api/service-program'
type Action = 'contact' | 'evidence' | 'propose' | 'review' | 'extend' | 'retry_refund' | 'finish_rearrange'
const route = useRoute()
const filters = reactive({ status: '', keyword: '', overdue: false })
const tabs = [{ label: '全部', value: '' }, { label: '待受理', value: 'submitted' }, { label: '待机构依据', value: 'evidence_pending' }, { label: '处理中', value: 'processing' }, { label: '待患者确认', value: 'proposed' }, { label: '待复核', value: 'review_requested' }, { label: '复核待确认', value: 'review_proposed' }, { label: '争议协调', value: 'disputed' }, { label: '待重新预约', value: 'awaiting_rebooking' }, { label: '退费执行中', value: 'executing' }, { label: '已结案', value: 'resolved' }]
const rows = ref<ServiceDispute[]>([]), total = ref(0), page = ref(1), loading = ref(false), error = ref(''), visible = ref(false), selected = ref<ServiceDispute | null>(null), actionVisible = ref(false), submitting = ref(false)
const replacementOptions = ref<ServiceAppointment[]>([])
const correctedOptions = ref<Array<{ id: number; name: string }>>([])
const form = reactive({ correctedEntitlementId: 0, replacementAppointmentId: 0, action: 'contact' as Action, ownerName: '', note: '', outcome: 'maintain', amountYuan: 0, costBearer: 'platform', clawbackNote: '', restoredExpiresAt: '', deadline: '', expectedUpdatedAt: '' })
const actionTitle = computed(() => ({ contact: '受理并登记首次联系', evidence: '登记机构执行依据', propose: '提出处理方案', review: '独立复核并反馈方案', extend: '说明延期与下一次反馈', retry_refund: '重新生成已接受方案的退费申请', finish_rearrange: '关联新的已确认预约完成重新安排' })[form.action])
async function load() { loading.value = true; error.value = ''; try { const result = await serviceProgramApi.disputes({ ...filters, page: page.value }); rows.value = result.list; total.value = result.total } catch { error.value = '异议列表加载失败，请重试' } finally { loading.value = false } }
function search() { page.value = 1; void load() }
function reset() { Object.assign(filters, { status: '', keyword: '', overdue: false }); search() }
async function open(row: ServiceDispute) { selected.value = await serviceProgramApi.dispute(row.id); visible.value = true }
async function refresh() { if (selected.value) selected.value = await serviceProgramApi.dispute(selected.value.id) }
async function act(action: Action) { if (!selected.value) return; Object.assign(form, { action, ownerName: selected.value.ownerName, note: '', outcome: selected.value.outcome || 'maintain', amountYuan: selected.value.refundAmountFen / 100, costBearer: selected.value.costBearer || 'platform', clawbackNote: selected.value.clawbackNote || '', restoredExpiresAt: selected.value.restoredExpiresAt || '', deadline: '', expectedUpdatedAt: selected.value.updatedAt, replacementAppointmentId: 0, correctedEntitlementId: selected.value.correctedEntitlementId || 0 }); if (['propose', 'review', 'finish_rearrange'].includes(action)) { const order = await serviceProgramApi.getOrder(selected.value.orderId); replacementOptions.value = order.plan?.appointments.filter(item => ['confirmed','arrived','completed'].includes(item.status) && item.entitlementId === selected.value!.entitlementId && new Date(item.createdAt).getTime() >= new Date(selected.value!.acceptedAt!).getTime()) || []; correctedOptions.value = order.plan?.entitlements.filter(item => item.id !== selected.value!.entitlementId && item.orderItem.kind !== 'goods' && item.totalQuantity > item.usedQuantity + item.reservedQuantity + item.refundFrozen + item.refundedQuantity).map(item => ({ id: item.id, name: item.orderItem.itemName })) || [] }; actionVisible.value = true }
async function save() { if (!selected.value || !form.note.trim()) { ElMessage.warning('请填写处理依据或说明'); return }; const proposal = ['propose','review'].includes(form.action); const refund = proposal && form.outcome === 'refund'; submitting.value = true; try { selected.value = await serviceProgramApi.disputeAction(selected.value.id, { action: form.action, correctedEntitlementId: proposal && form.outcome === 'correct_item' ? form.correctedEntitlementId : undefined, replacementAppointmentId: form.action === 'finish_rearrange' ? form.replacementAppointmentId : undefined, expectedUpdatedAt: form.expectedUpdatedAt, note: form.note.trim(), ownerName: form.action === 'contact' ? form.ownerName : undefined, outcome: proposal ? form.outcome : undefined, refundAmountFen: refund ? Math.round(form.amountYuan * 100) : undefined, costBearer: refund ? form.costBearer : undefined, clawbackNote: refund ? form.clawbackNote : undefined, restoredExpiresAt: proposal && ['restore','rearrange','correct_item'].includes(form.outcome) && form.restoredExpiresAt ? form.restoredExpiresAt : undefined, deadline: form.action === 'extend' ? form.deadline : undefined }); actionVisible.value = false; ElMessage.success('异议进度已更新'); await load() } finally { submitting.value = false } }
function statusText(value: string) { return tabs.find(tab => tab.value === value)?.label || value }
function outcomeText(value: string) { return ({ maintain: '维持记录', correct_item: '纠正实际项目', restore: '恢复权益', rearrange: '重新安排', refund: '例外退费' } as Record<string,string>)[value] || value }
function isOverdue(row: ServiceDispute) { return !!row.deadline && new Date(row.deadline).getTime() < Date.now() && row.status !== 'resolved' }
function formatTime(value: string) { return new Date(value).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', hour12: false }) }
function eventText(value: string) { return ({ submitted: '患者提交', contact: '客服首次联系', evidence: '机构依据已登记', propose: '处理方案已提出', review: '独立复核反馈', review_requested: '患者申请复核', disputed: '患者不接受，继续协调', accepted: '患者明确接受', refund_success: '例外退费成功并结案', extend: '反馈期限调整', retry_refund: '重新生成退费申请', compensation_created: '例外退费申请已生成', finish_rearrange: '重新预约已确认并关联' } as Record<string,string>)[value] || value }
function applyQuery() { filters.status = typeof route.query.status === 'string' ? route.query.status : ''; filters.overdue = route.query.overdue === 'true'; page.value = 1 }
watch(() => route.query, () => { applyQuery(); void load() })
onMounted(() => { applyQuery(); void load() })
</script>
<style scoped>
.disputes-page { display:flex; flex-direction:column; gap:16px; }.tabs { padding:0 16px; background:#fff; border:1px solid var(--el-border-color-lighter); border-radius:12px; }.tabs :deep(.el-tabs__header) { margin:0; }.muted { margin-top:6px; color:var(--el-text-color-secondary); font-size:12px; }.pagination { display:flex; justify-content:space-between; padding:16px; background:#fff; border-radius:12px; font-size:13px; }.summary,.panel { padding:18px; margin-bottom:18px; border:1px solid var(--el-border-color-lighter); border-radius:12px; }.summary { background:var(--el-fill-color-light); }.panel h4 { margin:0 0 12px; } p { white-space:pre-wrap; overflow-wrap:anywhere; color:var(--el-text-color-regular); line-height:1.7; font-size:13px; }.overdue { color:var(--el-color-danger); }.footer { display:flex; flex-wrap:wrap; justify-content:flex-end; gap:8px; }.action-form { margin-top:18px; }
</style>
